def affine_grid_generator_backward(grad_output, size, align_corners):
    """
    Compute the backward pass of affine_grid_generator using Triton.

    Args:
        grad_output: Gradient w.r.t. the grid output.
            2D: [N, H, W, 2]
            3D: [N, D, H, W, 3]
        size: The size of the input tensor [N, C, H, W] or [N, C, D, H, W]
        align_corners: Whether to align corners.

    Note: Only floating-point dtypes are supported (float16, bfloat16, float32, float64).
          Internal accumulation is always done in float32 for numerical stability.

    Returns:
        grad_theta: Gradient w.r.t. theta.
            2D: [N, 2, 3]
            3D: [N, 3, 4]
    """
    assert grad_output.dtype in (
        torch.float16,
        torch.bfloat16,
        torch.float32,
        torch.float64,
    ), f"affine_grid_generator_backward requires floating-point dtype, got {grad_output.dtype}"
    grad_output = grad_output.contiguous()
    N = size[0]

    if len(size) == 4:
        # 2D case: size = [N, C, H, W], grad_output = [N, H, W, 2]
        H, W = size[2], size[3]
        grad_theta = torch.empty(
            N, 2, 3, device=grad_output.device, dtype=grad_output.dtype
        )

        # Choose BLOCK_W: cover W in as few tiles as possible
        BLOCK_W = min(triton.next_power_of_2(W), 1024)
        if BLOCK_W < 32:
            BLOCK_W = 32

        # Use per-element parallelism when N is small and HW is large
        # This gives better GPU utilization for cases like N=1, H=1024, W=1024
